import { getAlignClasses } from "../../../core/helpers/utils/align.js";
import { attr } from "../../../core/helpers/utils/attr.js";
import { cssInline } from "../../../core/helpers/utils/css.js";
import { getCaptionWrapper } from "../../../core/helpers/utils/image-caption.js";
import { readAlign } from "./align.js";
import { readLink } from "./link.js";
import { readMargins } from "./margin.js";
import { readSizes } from "./size.js";
/**
 * Read values from image and set it to state
 * @private
 */
export async function readValuesFromImage(j, state) {
    const { sourceImage: image, values } = state;
    // A captioned image's caption element holds its place on the page and
    // its width
    const wrapper = getCaptionWrapper(j, image);
    const box = wrapper !== null && wrapper !== void 0 ? wrapper : image;
    values.imageCaption = Boolean(wrapper);
    readAlign(box, values, getAlignClasses(j, box));
    // Border radius
    values.borderRadius =
        parseInt(cssInline(image, 'border-radius') || '0', 10) || 0;
    // Id
    values.id = attr(image, 'id') || '';
    // Title
    values.imageTitle = attr(image, 'title') || '';
    // Alt
    values.imageAlt = attr(image, 'alt') || '';
    // Style
    values.style = attr(image, 'style') || '';
    // Classes
    values.classes = (attr(image, 'class') || '').replace(/jodit_focused_image[\s]*/, '');
    // Margins
    readMargins(box, values, state);
    // Link
    readLink(state, j, values);
    // Src
    values.imageSrc = attr(image, 'src') || '';
    // Image size
    return readSizes(image, values, state, wrapper);
}
